rowdata.pyStepsJavaSource:
String strReportOnClass = tools.getParamValue("pyObjClass");
String strListName = tools.getParamValue("pyListName");
String strAction = tools.getParamValue("Action");
String strLimitToProperty1 = tools.getParamValue("p1");
String strPropertyValue1 = tools.getParamValue("v1");
String strLimitToProperty2 = tools.getParamValue("p2");
String strPropertyValue2 = tools.getParamValue("v2");

String strPageName = tools.getParamValue("pageName");
String strShowResults = tools.getParamValue("showResults");
String strMaxRecords = tools.getParamValue("maxRecords");
if (strMaxRecords.length() == 0) strMaxRecords = pega_wb_lookuplist.getDefaultMax();

boolean bReturnAsPage = false;
if (strShowResults.equalsIgnoreCase("NO")) bReturnAsPage = true;

String tempPageName = "";

if(strPageName.trim().length() == 0)  
  tempPageName = "pyLookupPage";
else
  tempPageName = strPageName;

java.util.List<String> errorMessages = new java.util.ArrayList<>();

ClassInfo classInfo = tools.getDictionary().getClassInfo(strReportOnClass);
if(classInfo!=null && classInfo.isConcrete())
{
	if (!strLimitToProperty1.trim().equals(""))
	{
		ImmutablePropertyInfo propertyInfo = classInfo.getImmutableTerminalPropertyInfo(strLimitToProperty1);
			if(propertyInfo == null)
			{
				errorMessages.add("pzInvalidProperty \t" + StringUtils.crossScriptingFilter(strLimitToProperty1));
			}
	}

	if (!strLimitToProperty2.trim().equals(""))
	{
			ImmutablePropertyInfo propertyInfo = classInfo.getImmutableTerminalPropertyInfo(strLimitToProperty2);
			if(propertyInfo == null)
			{
				errorMessages.add("pzInvalidProperty \t" + StringUtils.crossScriptingFilter(strLimitToProperty2));
			}	
	}
}else{
    errorMessages.add("pzInvalidClass \t" + StringUtils.crossScriptingFilter(strReportOnClass));
}


if (errorMessages.size() > 0)
{
	ClipboardPage browsePage = tools.createPage("Code-Pega-List", tempPageName);
	for(String errMsg : errorMessages) {
		if(!StringUtils.isBlank(errMsg))
			browsePage.addMessage(errMsg);
	}
	if(!bReturnAsPage) {
		tools.getThread().getThreadPage().putString("pyXMLStream", browsePage.getXML());
		browsePage.removeFromClipboard();
	}
} else {

	String useLegacyLightweightResults = tools.getParamValue("useLegacyLightweightResults");
                   if("".equals(useLegacyLightweightResults )) {
                      useLegacyLightweightResults = tools.getParamValue("useLightweightResults");
                   }
                   String useLightweightList= tools.getParamValue("useLightweightList");
         boolean bEnableLookupListsDefault = enableLookupLists.equals("Enabled") ? true : false;
         boolean flag = false;         

         if(disableLookupLists.equals("Default")){
            flag =  bEnableLookupListsDefault;
         }else if(disableLookupLists.equals("Enabled")){
            flag = true; 
         }else if(disableLookupLists.equals("Disabled")){
            flag = false;
         }  

	if (strLimitToProperty1.equals("pyClassName")) {
		ClassInfo classInfo1 = tools.getDictionary().getClassInfo(strPropertyValue1);
		strPropertyValue1 = classInfo1.getClassName();
	} 

	if (strLimitToProperty2.equals("pyClassName")) {
		ClassInfo classInfo2 = tools.getDictionary().getClassInfo(strPropertyValue2);
		strPropertyValue2 = classInfo2.getClassName();
	}

         pega_rulesengine_lookuplist.process(strReportOnClass ,strListName ,strAction ,
	       strLimitToProperty1 , strPropertyValue1 , strLimitToProperty2 , strPropertyValue2, bReturnAsPage , strPageName , 
                strMaxRecords, useLegacyLightweightResults , flag, useLightweightList);
}
